INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_deposit','stat_civil_lease','rental holding fee refund',1,'holding-fee refundandfee','holding-fee refund、service fee、repair  responsibilities are named in writing，a verbal promise without written proof。');
